<template><view class="mes-page"><view class="mes-header"><view><view class="mes-title">操作日志</view><view class="mes-description">服务端记录的实际操作人、时间、原因和版本。</view></view></view><view v-if="error" class="mes-error">{{ error }}<button size="mini" :disabled="loading" @click="load">重新加载记录</button></view><template v-if="authorized"><view class="mes-toolbar"><uni-data-select v-model="type" :localdata="types" :clear="false" /><input v-model="keyword" class="mes-search" placeholder="批号或资料名称" @confirm="search" /><button size="mini" :disabled="loading" @click="search">查询</button><button size="mini" :disabled="loading || !rows.length" @click="exportRows">导出当前页</button></view><view class="mes-table"><uni-table border :loading="loading" :emptyText="error ? '读取失败，请重新加载' : '暂无操作记录'"><uni-tr><uni-th>资料 / 批号</uni-th><uni-th>版本</uni-th><uni-th>操作人</uni-th><uni-th>时间</uni-th><uni-th>原因及变化字段</uni-th></uni-tr><uni-tr v-for="row in rows" :key="row._id"><uni-td>{{ row.label }}</uni-td><uni-td>V{{ row.previousVersion }} → V{{ row.version }}</uni-td><uni-td>{{ row.actorName }}</uni-td><uni-td>{{ time(row.at) }}</uni-td><uni-td>{{ row.reason }}<view class="mes-muted">{{ (row.changedFields || []).join('、') }}</view></uni-td></uni-tr></uni-table></view><uni-pagination :total="total" :page-size="20" :current="page" @change="changePage" /></template></view></template>
<script>
import { requireMesAdmin, formatMesDate } from '@/utils/mes-api.js';
import { callOperations, exportCsv } from '@/utils/operations-admin.js';
export default { data() { return { authorized: false, type: 'jobs', keyword: '', rows: [], total: 0, page: 1, loading: false, error: '', types: [{ value: 'claims', text: '人员认领审核' }, { value: 'attendance', text: '考勤记录' }, { value: 'jobs', text: '工单执行' }, { value: 'schedules', text: '排班' }, { value: 'handovers', text: '交接班' }, { value: 'exceptions', text: '异常' }, { value: 'personnel', text: '人员' }, { value: 'processes', text: '工序' }, { value: 'shifts', text: '班次' }, { value: 'resources', text: '设备与模具' }, { value: 'workshops', text: '车间' }] } }, async onLoad() { await this.load() }, methods: {
time: formatMesDate, search() { this.page = 1; this.load() }, changePage(event) { this.page = event.current; this.load() },
async load() { if (this.loading) return; this.loading = true; this.error = ''; this.rows = []; try { if (!this.authorized) { await requireMesAdmin(); this.authorized = true; } const result = await callOperations('audit', { type: this.type, keyword: this.keyword, page: this.page, pageSize: 20 }); this.rows = result.list; this.total = result.total } catch (error) { this.error = error.message; this.total = 0 } finally { this.loading = false } },
exportRows() { exportCsv('生产操作追溯_当前页.csv', [{ key: 'label', label: '资料' },{ key: 'version', label: '版本' },{ key: 'actorName', label: '操作人' },{ key: 'time', label: '时间' },{ key: 'reason', label: '原因' }],this.rows.map(row => ({...row,time:formatMesDate(row.at)}))) }
} };
</script><style lang="scss" scoped>@import './operations.scss';</style>
